            obj = fdp.ConsumeUnicodeNoSurrogates(64)
        elif choice == 3:
            obj = [fdp.ConsumeInt(4) for _ in range(fdp.ConsumeIntInRange(0, 10))]
        else:
            obj = {fdp.ConsumeUnicodeNoSurrogates(8): fdp.ConsumeInt(4)}
